function list(s: string, dict: Record<string, string> = PHRASES): string {
  return s.split(/,\s*/).map((x) => dict[x.trim()] ?? ar(x.trim())).join("، ");
}

const RULES: [RegExp, (...m: string[]) => string][] = [
  [/^Risk (\d+) \/ confidence (\d+)% on Tier-(\d) \(auto threshold (\d+)\)$/,
    (_, r, c, t, th) => `الخطورة ${r} والثقة ${c}% على Tier-${t} (عتبة الاحتواء الآلي ${th})`],
  [/^Confidence (\d+)% < (\d+)% \((\d+) independent sources?\): no automatic containment$/,
    (_, c, min, n) => `الثقة ${c}% أقل من ${min}% (عدد المصادر المستقلة: ${n}): لا احتواء آلي`],
  [/^Medium band \((\d+) <= risk < (\d+)\)$/, (_, lo, hi) => `خطورة متوسطة (بين ${lo} و${hi})`],
  [/^Risk (\d+) < (\d+): monitor and enrich$/, (_, r, lo) => `الخطورة ${r} أقل من ${lo}: مراقبة وجمع معلومات إضافية`],
  [/^Risk (\d+) < (\d+): monitor$/, (_, r, lo) => `الخطورة ${r} أقل من ${lo}: مراقبة فقط`],
  [/^(\d+) assets hit in (\S+): restrict SMB\/RDP inside this segment only$/,
    (_, n, seg) => `${n} أجهزة مصابة في الشبكة الفرعية ${seg}: منع مشاركة الملفات وسطح المكتب البعيد داخلها فقط`],
  [/^Circuit breaker: (\d+) automatic containments in 10 min, human approval required$/,
    (_, n) => `قاطع الحماية: ${n} حالات احتواء آلي مفتوحة خلال 10 دقائق، يلزم موافقة بشرية لمنع عزل جماعي`],
  [/^Response Memory: approved pattern (\w+) matched at ([\d.]+)% \(no confirmation pause\)$/,
    (_, id, s) => `ذاكرة الاستجابة: نمط معتمد (${id}) تطابق بنسبة ${s}%، لذا لا توقف للتأكيد`],
  [/^Isolation controller unavailable: (.+) not applied within the (\d+)s deadline$/,
    (_, cmds, s) => `أداة العزل لا تستجيب: لم يُطبَّق (${list(cmds)}) خلال مهلة ${s} ثانية`],
  [/^Verification Gate failed (\d+) times: (.+)$/, (_, n, checks) => `فشلت بوابة التحقق ${n} مرات: ${list(checks)}`],
  [/^retrying: \[(.+)\]$/, (_, c) => `إعادة المحاولة: ${list(c.replace(/'/g, ""))}`],
  [/^Outbound C2-like traffic to ([\d.]+):(\d+)(?: on (.+))?$/,
    (_, ip, port, h) => `اتصال خارجي يشبه خادم تحكم إلى ${ip}:${port}${h ? ` من ${h}` : ""}`],
  [/^Beaconing to ([\d.]+) every ~(\d+)s(?: on (.+))?$/, (_, ip, s, h) => `اتصال دوري بـ ${ip} كل ${s} ثانية تقريبًا${h ? ` من ${h}` : ""}`],
  [/^(\S+) spawned with network activity(?: on (.+))?$/, (_, p, h) => `${p} شُغّل مع نشاط شبكي${h ? ` على ${h}` : ""}`],
  [/^Lateral fan-out to (\d+) internal hosts(?: on (.+))?$/, (_, n, h) => `محاولة وصول إلى ${n} أجهزة داخلية${h ? ` من ${h}` : ""}`],
  [/^DNS tunneling via (\S+)(?: on (.+))?$/, (_, d, h) => `تهريب بيانات عبر DNS باستخدام ${d}${h ? ` من ${h}` : ""}`],
  [/^Large outbound transfer to ([\d.]+)(?: on (.+))?$/, (_, ip, h) => `نقل كمية كبيرة من البيانات إلى ${ip}${h ? ` من ${h}` : ""}`],
  [/^Impossible travel for (\S+)(?: on (.+))?$/, (_, u, h) => `دخول مستحيل جغرافيًا للمستخدم ${u}${h ? ` على ${h}` : ""}`],
  [/^IAM persistence API: (\S+)(?: on (.+))?$/, (_, api, h) => `استدعاء صلاحيات لتثبيت الوجود في السحابة: ${api}${h ? ` على ${h}` : ""}`],
  [/^Threat-intel match: (\S+)(?: on (.+))?$/, (_, ind, h) => `تطابق مع استخبارات التهديد: ${ind}${h ? ` على ${h}` : ""}`],
  [/^Behavioral anomaly: (.+?)(?: on ([A-Z0-9.-]+))?$/, (_, m, h) => `سلوك غير طبيعي: ${ar(m)}${h ? ` على ${h}` : ""}`],
  [/^(.+) on ([A-Z][A-Z0-9-]+|\d+\.\d+\.\d+\.\d+)$/, (_, what, h) => `${ar(what)} على ${h}`],
  [/^(\d+) detections combined \(noisy-OR\)$/, (_, n) => `${n} إشارات كشف مجتمعة`],
  [/^(\d+) independent sensors agree$/, (_, n) => `${n} أجهزة استشعار مستقلة متفقة`],
  [/^(\d+) independent sources?: (.+)$/, (_, n, s) => `${n} مصادر مستقلة: ${list(s, SOURCES)}`],
  [/^(\d+) peers, (\d+) dependents, criticality (\w+)$/,
    (_, p, d, c) => `${p} أجهزة مجاورة، ${d} أنظمة تعتمد عليه، أهمية ${PHRASES[c] ?? c}`],
  [/^IoC reputation (\d+)$/, (_, n) => `سمعة العنوان ${n}`],
  [/^UEBA deviation ([\d.]+)$/, (_, n) => `انحراف سلوكي ${n}`],
  [/^probe:host -> (.+)$/, (_, h) => `الجهاز لا يصل إلى ${h}`],
  [/^host -> (.+)$/, (_, h) => `الجهاز لا يصل إلى ${h}`],
  [/^observe:(\d+)$/, (_, n) => `فحص المراقبة ${n}`],
  [/^(\w+) (\d+)\/(\d+)$/, (_, lvl, a, b) => `${LEVELS[lvl] ?? lvl}: ${a} من ${b}`],
  [/^approved escalation to (\w+)$/, (_, lvl) => `موافقة على التصعيد إلى ${LEVELS[lvl] ?? lvl}`],
  [/^harden entry: (.+)$/, (_, e) => `تحصين نقطة الدخول: ${ar(e)}`],
  [/^containment (\w+): \[SIMULATED\] (\w+) applied to (.+)$/,
    (_, lvl, cmd, tgt) => `${LEVELS[lvl] ?? lvl}: [محاكاة] طُبّق «${PHRASES[cmd] ?? cmd}» على ${tgt}`],
  [/^containment (\w+): (.+) \(simulated\) unavailable: gave up after (\d+) attempts at the deadline$/,
    (_, lvl, tool, n) => `${LEVELS[lvl] ?? lvl}: أداة ${tool} (محاكاة) لا تستجيب، توقفت المحاولات بعد ${n} محاولات عند انتهاء المهلة`],
  [/^\[SIMULATED\] (\w+) applied to (.+)$/, (_, cmd, tgt) => `[محاكاة] طُبّق «${PHRASES[cmd] ?? cmd}» على ${tgt}`],
  [/^(.+) \(simulated\) unavailable: gave up after (\d+) attempts at the deadline$/,
    (_, tool, n) => `أداة ${tool} (محاكاة) لا تستجيب، توقفت المحاولات بعد ${n} محاولات`],
  [/^(.+) \(simulated\)$/, (_, tool) => `${tool} (محاكاة)`],
  [/^Approval is not possible in state (\w+)$/, (_, s) => `لا يمكن الموافقة في مرحلة «${STATES[s] ?? s}»`],
  [/^Pattern is already (\w+)$/, (_, s) => `النمط ${STATES[s] ?? s} بالفعل`],
  [/^Unknown command (\w+)$/, (_, c) => `أمر غير معروف: ${c}`],
  [/^(\S+) already approved (\w+): a different approver is required$/,
    (_, who, lvl) => `${who} وافق بالفعل على «${LEVELS[lvl] ?? lvl}»: يلزم شخص مختلف للموافقة الثانية`],
  [/^Tier-(\d)$/, (_, n) => `Tier-${n}`],
  [/^(MISP|OpenCTI): (.+)$/, (_, f, t) => `${f}: ${PHRASES[t.charAt(0).toUpperCase() + t.slice(1)] ?? PHRASES[t] ?? t}`],
];

function ar(s: string): string {
  if (s in PHRASES) return PHRASES[s];
  if (s in LEVELS) return LEVELS[s];
  if (s in STATES) return STATES[s];
  for (const [re, fn] of RULES) {
    const m = s.match(re);
    if (m) return fn(...m);
  }
  return s;
}

/** Readable English for codes the backend emits (commands, checks, factors, audit actions, evidence). */
const EN: Record<string, string> = {
  APPLY_MICROSEGMENTATION: "Apply micro-segmentation", BLOCK_C2: "Block C2 server", CLOUD_SG_UPDATE: "Update cloud security groups",
  CORDON_NODE: "Cordon node", DNS_BLOCK: "Block malicious domain", DRAIN_FROM_POOL: "Drain from service pool",
  ENABLE_ENHANCED_MONITORING: "Enable enhanced monitoring", HARDEN_ENTRY_POINT: "Harden entry point", ISOLATE_ASSET: "Isolate asset",
  PROTECT_DATABASE: "Protect databases", RESTRICT_NETWORK: "Restrict network", RESTRICT_SEGMENT_LATERAL: "Block movement inside the segment",
  REVOKE_SESSION: "Revoke active sessions", ROTATE_SECRETS: "Rotate passwords and keys", SET_NETWORK_STAGE: "Set re-entry stage",
  WITHDRAW_SERVICE_RECORD: "Withdraw service record", RUN_VERIFICATION: "Run verification",
  APPROVAL_RECORDED: "Approval recorded", AUTOMATION_CONFIRMED: "Automation confirmed", AWAITING_CONFIRMATION: "Awaiting confirmation",
  CHANGE_WINDOW_SET: "Change window updated", DEMO_RESET: "Demo reset", ENTRY_POINT_HARDENED: "Entry point hardened",
  ESCALATED_TO_EMERGENCY_QUEUE: "Sent to the emergency queue", EVENTS_CORRELATED: "Events correlated",
  FALSE_POSITIVE_ROLLBACK: "Rolled back as false positive", INCIDENT_DETECTED: "Incident detected",
  IOB_DURING_OBSERVATION: "Indicator returned during observation", LOGIN_FAILED: "Sign-in failed",
  RESPONSE_PATTERN_APPLIED: "Response pattern applied", RESPONSE_PATTERN_SAVED: "Response pattern saved",
  RESPONSE_PATTERN_APPROVED: "Response pattern approved", RESPONSE_PATTERN_REJECTED: "Response pattern rejected",
  SIMULATION_STARTED: "Simulation started", THREAT_CONTAINED: "Threat contained", THREAT_NEUTRALIZED: "Threat neutralized",
  VERIFICATION_GATE_FAILED: "Verification gate failed", INCIDENT_CLOSED: "Incident closed",
  signal_severity: "Signal severity", source_correlation: "Source correlation", ioc_reputation: "Attacker IP reputation",
  asset_sensitivity: "Asset sensitivity", behavior_anomaly: "Behaviour anomaly", blast_radius: "Blast radius",
  independent_sources: "Independent sources", threat_intel: "Threat intelligence", evidence_strength: "Evidence strength",
  attribution_conflict: "Asset attribution conflict", change_window: "Change window",
  no_ioc: "No indicators of compromise", no_critical_vulns: "No critical vulnerabilities", autoruns_clean: "No suspicious autoruns",
  services_healthy: "Services healthy", edr_running: "Endpoint protection running", evidence_intact: "Evidence intact",
  firewall_policy: "Firewall policy applied", secrets_rotated: "Secrets rotated", behavior_normal: "Behaviour normal",
  disk_image: "Disk image", hash_manifest: "Hash manifest", memory_dump: "Memory dump", network_pcap: "Network capture",
  process_tree: "Process tree", timeline: "Timeline", succeeded: "Succeeded", failed: "Failed", released: "Lifted",
  rolled_back: "Rolled back", "known-bad": "Known bad", "on-prem": "On-premises",
  "internet egress from host": "Host cannot reach the internet",
  "soc-jump-01 -> host (investigation, inbound only)": "Investigation host can reach the host (inbound only)",
  DE: "Germany", MD: "Moldova", NL: "Netherlands", RO: "Romania", RU: "Russia", US: "United States",
};

function en(s: string): string {
  if (s in EN) return EN[s];
  let m = s.match(/^gate:(\w+)$/);
  if (m) return EN[m[1]] ?? m[1];
  m = s.match(/^probe:(.+)$/);
  if (m) return EN[m[1]] ?? en(m[1]);
  m = s.match(/^host -> (.+)$/);
  if (m) return `Host cannot reach ${m[1]}`;
  m = s.match(/^observe:(\d+)$/);
  if (m) return `Observation check ${m[1]}`;
  m = s.match(/^Verification Gate failed (\d+) times: (.+)$/);
  if (m) return `Verification gate failed ${m[1]} times: ${m[2].split(/,\s*/).map((c) => EN[c] ?? c).join(", ")}`;
  m = s.match(/^Isolation controller unavailable: (.+) not applied within the (\d+)s deadline$/);
  if (m) return `Isolation tool not responding: ${m[1].split(/,\s*/).map((c) => EN[c] ?? c).join(", ")} not applied within the ${m[2]} s deadline`;
  return s;
}

/** Translate backend text for display. Empty values render as an em dash. */
export function tr(lang: Lang, s: string | null | undefined): string {
  if (s == null || s === "") return "—";
  return lang === "en" ? en(s) : ar(s);
}

/** Translate a comma-separated list or an array (commands, sources). */
export function trList(lang: Lang, items: string[] | null | undefined): string {
  if (!items || !items.length) return "—";
  return lang === "en" ? items.map((x) => en(x)).join(", ") : items.map((x) => ar(x)).join("، ");
}
